START TRANSACTION;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (354, 'reglas_locales', 'accordion', '[{"titulo": "Reglas Generales", "contenido": "Regirán las reglas de la USGA adoptadas por la Federación Mexicana de Golf. Es responsabilidad de los jugadores conocerlas."}, {"titulo": "Hora de Salida", "contenido": "El jugador deberá hacer presencia en su respectiva área de salida 10 minutos antes de su horario estipulado, y deberá iniciar su ronda en la hora establecida por el comité. Si el jugador llega dentro de los 5 minutos posteriores a su horario, podrá jugar con 2 golpes de castigo; de no estar dentro de los límites de tiempo, el jugador será descalificado."}, {"titulo": "Límites del Campo", "contenido": "Está delimitado por estacas, líneas y marcas blancas en bardas. Donde existan estacas, postes o áreas marcadas, prevalecerá la línea de trazo de estaca a estaca. En el hoyo 10, a la altura de la salida de negras, la parte interna de la jardinera delimita el fuera de campo."}, {"titulo": "Terreno en Reparación", "contenido": "Identificado con líneas blancas."}, {"titulo": "Áreas de Penalidad Rojas", "contenido": "Identificadas con estacas rojas y delimitadas por líneas rojas."}, {"titulo": "Zonas de Dropeo", "contenido": "Son una opción de dropeo adicional. En el hoyo 14 habrá círculo de dropeo para el área de penalidad."}, {"titulo": "Árboles con Cajete", "contenido": "NO está permitido el alivio SIN CASTIGO."}, {"titulo": "Ranuras Alrededor de los Greenes", "contenido": "Está en efecto el MRL-8F-19. Si existe interferencia por una ranura, el jugador puede tomar alivio como sigue: Bola en el área general — alivio bajo la regla 16.1b (dropear la bola dentro del largo de un bastón del punto de alivio completo más cercano, sin acercarse al hoyo; no podrá dropearse dentro de green). POR CAMBIO DE CORTE NO HAY ALIVIO, EXCLUSIVAMENTE DE LA RANURA."}, {"titulo": "Obstrucciones Temporales Inamovibles (TIO)", "contenido": "Está en efecto el MRL F-23. Se consideran TIO los stands de patrocinadores, los automóviles en exhibición, cualquier anuncio publicitario que no puede ser removido con facilidad (de poder moverse con facilidad se considera obstrucción movible) y las cámaras de video colocadas para verificar un hole in one. El jugador podrá obtener alivio sin castigo de acuerdo con el procedimiento del MRL F-23; el alivio está permitido a ambos lados de la obstrucción."}, {"titulo": "Obstrucciones Inamovibles Cerca de los Greenes", "contenido": "Está en efecto el MRL F-5.1. El jugador puede tomar alivio bajo la regla 16.1b si una obstrucción inamovible está en la línea de juego y la obstrucción está en o dentro de la longitud de dos bastones del green y dentro de la longitud de dos bastones de la bola. Excepción: no hay alivio si el jugador elige una línea de juego claramente irrazonable."}, {"titulo": "Obstrucciones Inamovibles", "contenido": "Serán consideradas obstrucciones inamovibles: bancas, jardineras, satélites de riego, tambos de arena, señalética, postes de lámparas, postes, etc. El jugador podrá dropearse sin castigo dentro del área de un bastón buscando el punto de alivio más cercano, sin acercarse al hoyo."}, {"titulo": "Caminos de Concreto, Piedra, Adoquín y Asfalto", "contenido": "Si la bola de un jugador reposa en estas áreas, el jugador podrá dropearse sin castigo dentro del área de un bastón desde el punto de alivio más cercano sin acercarse al hoyo."}, {"titulo": "Práctica", "contenido": "Están en efecto los modelos de regla local I-1.2 e I-2. Antes y después de una ronda, un jugador puede practicar en las áreas de práctica designadas. Las Reglas 5.2b y 5.5b se modifican: un jugador no debe practicar en el campo de la competencia antes o entre rondas, y entre el juego de dos hoyos no debe ejecutar ningún golpe de práctica en o cerca del green del hoyo recién terminado, ni probar la superficie de ese green frotando o haciendo rodar una bola. Penalidad general: 2 golpes de castigo."}, {"titulo": "Galería", "contenido": "El comportamiento de la galería estará sujeto a los reglamentos del club y a las reglas de etiqueta del golf. Queda estrictamente prohibido el uso de carritos de golf, ya sean particulares o propios del club, para galería."}, {"titulo": "Aparatos de Sonido y Celulares", "contenido": "Se permite su uso, pero debe hacerse con discreción, sin distraer a otros jugadores y sin retrasar el juego. Primera infracción: penalidad general. Segunda infracción: descalificación."}, {"titulo": "Bola Enterrada por su Propio Impacto en Área General", "contenido": "En cualquier lugar a través del campo, una bola enterrada por su propio impacto deberá ser marcada, y el jugador podrá tomar alivio sin castigo dropeando la bola dentro del largo de un bastón del punto de alivio completo más cercano, sin acercarse al hoyo."}, {"titulo": "Suspensión del Juego y Plan de Evacuación", "contenido": "El juego podrá ser suspendido por tormenta eléctrica o lluvia torrencial si así lo considera el comité organizador, de acuerdo con las siguientes señales sonoras:\\n• Suspensión inmediata: una nota prolongada.\\n• Suspensión del juego: tres notas consecutivas.\\n• Reanudación del juego: dos notas, una prolongada y otra breve."}, {"titulo": "Penalidad por Juego Lento", "contenido": "El comité de golf, a través del juez de reglas, está facultado para castigar el juego lento de la siguiente manera:\\n• Primera infracción: un golpe de castigo.\\n• Segunda infracción: dos golpes de castigo.\\n• Reincidencia: descalificación."}, {"titulo": "Entrega de Tarjetas", "contenido": "Al término de la ronda, el jugador deberá verificar su score, firmar su tarjeta, asegurarse de que el anotador (testigo) haya firmado su tarjeta, y entregarla inmediatamente después de concluir su ronda. En caso de aclaración o inconformidad, deberá presentarse por escrito de inmediato al comité para su resolución."}, {"titulo": "Jueces", "contenido": "Las decisiones del juez y comité de reglas son inapelables."}, {"titulo": "Duda en Aplicación de Reglas", "contenido": "Durante el juego, en caso de dudas en la aplicación de una regla, el jugador podrá completar el hoyo con 2 bolas, debiendo aclarar la situación a sus contrincantes en lo que el juez de reglas se hace presente para aplicar una decisión. La situación deberá quedar resuelta forzosamente antes de firmar su tarjeta."}, {"titulo": "Zona Prohibida de Juego", "contenido": "Alivio obligatorio sin castigo. Todas las jardineras y el vivero de green que se encuentra a la altura de las marcas rojas del hoyo 16 se consideran zona prohibida para jugar. El jugador deberá tomar alivio sin penalidad bajo la regla 16.1b (dropeando la bola dentro del largo de un bastón del punto de alivio completo más cercano, sin acercarse al hoyo)."}, {"titulo": "Oficiales de Reglas del Torneo", "contenido": "Montserrat Bayardo — Tel. 33 3190 7590.\\nAndrés Castellanos — Tel. 33 3492 4203."}]', 1)
